begin;
select plan(50);
select set_config('test.weekly_amr',floor(extract(epoch from clock_timestamp()-interval '2 minutes'))::text,true);
insert into auth.users(id,aud,role,email,email_confirmed_at,created_at,updated_at) values('c2100000-0000-4000-8000-000000000001','authenticated','authenticated','weekly-manager@example.invalid',now(),now(),now());
insert into auth.identities(id,provider_id,user_id,identity_data,provider) values(gen_random_uuid(),'weekly-manager','c2100000-0000-4000-8000-000000000001','{"sub":"weekly-manager","email":"weekly-manager@example.invalid","email_verified":true}','google');
insert into auth.sessions(id,user_id,created_at,aal) values('c2200000-0000-4000-8000-000000000001','c2100000-0000-4000-8000-000000000001',now()-interval '3 minutes','aal2');
insert into auth.mfa_amr_claims(id,session_id,created_at,updated_at,authentication_method)
select gen_random_uuid(),'c2200000-0000-4000-8000-000000000001',to_timestamp(current_setting('test.weekly_amr')::bigint),to_timestamp(current_setting('test.weekly_amr')::bigint),method from unnest(array['oauth','totp'])method;
insert into public.organizations(id,code,name) values('c2300000-0000-4000-8000-000000000001','weekly-synthetic','合成機構');
insert into public.branches(id,organization_id,code,name) values('c2400000-0000-4000-8000-000000000001','c2300000-0000-4000-8000-000000000001','main','合成分支');
insert into public.profiles(id,display_name,kind) values('c2100000-0000-4000-8000-000000000001','合成主管','staff');
insert into public.memberships(id,organization_id,branch_id,profile_id,status,starts_at) values('c2500000-0000-4000-8000-000000000001','c2300000-0000-4000-8000-000000000001','c2400000-0000-4000-8000-000000000001','c2100000-0000-4000-8000-000000000001','active',now()-interval '1 year');
insert into public.membership_roles(membership_id,role_id) values('c2500000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000003');
insert into public.clients(id,organization_id,branch_id,client_code,display_name,admitted_on) values('c2600000-0000-4000-8000-000000000001','c2300000-0000-4000-8000-000000000001','c2400000-0000-4000-8000-000000000001','C-1','合成個案',(now() at time zone 'Asia/Taipei')::date);
insert into private.reauth_challenges(id,user_id,session_id,nonce_sha256,idempotency_key,issued_jwt_iat,created_at,expires_at,consumed_at,consumed_jwt_iat,factor_method,factor_verified_at)
values('c2700000-0000-4000-8000-000000000001','c2100000-0000-4000-8000-000000000001','c2200000-0000-4000-8000-000000000001',repeat('1',64),gen_random_uuid(),now()-interval '2 minutes',now()-interval '2 minutes',now()+interval '5 minutes',now()-interval '1 minute',now()-interval '1 minute','totp',now()-interval '1 minute');
insert into private.reauth_events(user_id,session_id,challenge_id,aal,verification_method,verified_at) values('c2100000-0000-4000-8000-000000000001','c2200000-0000-4000-8000-000000000001','c2700000-0000-4000-8000-000000000001','aal2','totp',now()-interval '1 minute');
select set_config('request.jwt.claims',jsonb_build_object('sub','c2100000-0000-4000-8000-000000000001','session_id','c2200000-0000-4000-8000-000000000001','role','authenticated','aud','authenticated','aal','aal2','is_anonymous',false,'email','weekly-manager@example.invalid','iat',floor(extract(epoch from now())),'exp',floor(extract(epoch from now()+interval '30 minutes')),'amr',jsonb_build_array(jsonb_build_object('method','oauth','timestamp',current_setting('test.weekly_amr')::bigint),jsonb_build_object('method','totp','timestamp',current_setting('test.weekly_amr')::bigint)))::text,true);

select ok((select bool_and(relrowsecurity and relforcerowsecurity) from pg_class where oid in ('private.client_document_versions'::regclass,'private.client_document_scan_results'::regclass,'private.client_document_review_versions'::regclass)),'document metadata and review stores force RLS');
select ok(not has_table_privilege('authenticated','private.client_document_versions','select,insert,update,delete'),'no browser metadata access');
select ok(not has_table_privilege('service_role','private.client_document_versions','select,insert,update,delete'),'worker gets bounded RPC only, not table grants');
select ok(not has_function_privilege('authenticated','public.complete_client_document_scan(uuid,text,text,text)','execute'),'browser cannot forge scan verdict');
select ok(has_function_privilege('service_role','public.complete_client_document_scan(uuid,text,text,text)','execute'),'worker scan registration is explicit');
select ok(not (select prosecdef from pg_proc where oid='public.reserve_client_document(uuid,uuid,jsonb)'::regprocedure),'public reserve remains invoker');
create schema if not exists storage;
create table if not exists storage.objects(id uuid primary key default gen_random_uuid(),bucket_id text not null,name text not null);
create function pg_temp.doc_input(p_extra jsonb default '{}') returns jsonb language sql as $$ select jsonb_build_object('clientId','c2600000-0000-4000-8000-000000000001','category','identity_front','expectedDocumentVersion',0,'idempotency_key','d1800000-0000-4000-8000-000000000001','sha256',repeat('a',64),'mimeType','image/png','fileSizeBytes',64)||p_extra; $$;
create function pg_temp.doc_reserve(p_extra jsonb default '{}') returns jsonb language sql as $$ select receipt from public.reserve_client_document('c2300000-0000-4000-8000-000000000001','c2400000-0000-4000-8000-000000000001',pg_temp.doc_input(p_extra));$$;
create function pg_temp.doc_read() returns jsonb language sql as $$ select payload from public.client_documents_snapshot('c2300000-0000-4000-8000-000000000001','c2400000-0000-4000-8000-000000000001','c2600000-0000-4000-8000-000000000001');$$;
create function pg_temp.doc_review(p_extra jsonb default '{}') returns jsonb language sql as $$ select receipt from public.review_client_document('c2300000-0000-4000-8000-000000000001','c2400000-0000-4000-8000-000000000001',jsonb_build_object('clientId','c2600000-0000-4000-8000-000000000001','category','identity_front','expectedDocumentVersion',1,'expectedReviewVersion',0,'decision','reviewed','reason','合成文件已核對','idempotency_key','d1800000-0000-4000-8000-000000000009')||p_extra);$$;
set local role anon;
select throws_ok($$select pg_temp.doc_read()$$,'42501',null,'anonymous cannot read documents');
reset role;
set local role authenticated;
select throws_ok($$select pg_temp.doc_reserve()$$,'42501',null,'unapproved Google account cannot reserve upload');
reset role;
insert into private.executive_access_policy(allowed_user_id,allowed_email,google_subject,enabled,approval_reference) values('c2100000-0000-4000-8000-000000000001','weekly-manager@example.invalid','weekly-manager',true,'synthetic document test');
set local role authenticated;
select is(jsonb_array_length(pg_temp.doc_read()->'rows'),6,'six explicit categories are returned');
select is(pg_temp.doc_read()->'rows'->0->>'status','missing','missing evidence is not completed');
select is(pg_temp.doc_reserve()->>'version','1','authorized actor reserves immutable version');
select is(pg_temp.doc_reserve()->>'replayed','true','same operation resolves same reservation');
select throws_ok($$select pg_temp.doc_reserve('{"sha256":"bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb"}')$$,'23505',null,'changed replay rejected');
select throws_ok($$select pg_temp.doc_reserve(jsonb_build_object('idempotency_key',gen_random_uuid()))$$,'40001',null,'stale upload base rejected');
select is(pg_temp.doc_read()->'rows'->0->>'status','scanning','reserved document is awaiting scanner');
select is(pg_temp.doc_read()->'rows'->0->>'canDownload','false','unscanned document cannot be downloaded');
select throws_ok($$select pg_temp.doc_review()$$,'22023',null,'review cannot invent clean scan evidence');
select throws_ok($$select public.complete_client_document_scan(gen_random_uuid(),repeat('a',64),'clean','test-scanner')$$,'42501',null,'direct browser scan injection rejected');
select throws_ok($$select public.client_documents_snapshot('c2300000-0000-4000-8000-000000000001',gen_random_uuid(),'c2600000-0000-4000-8000-000000000001')$$,'42501',null,'cross branch metadata denied');
reset role;
select set_config('test.document_id',(select id::text from private.client_document_versions where category='identity_front'),true);
select set_config('test.document_original_jwt',current_setting('request.jwt.claims'),true);
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select throws_ok($$select public.complete_client_document_scan(current_setting('test.document_id')::uuid,repeat('b',64),'clean','test-scanner')$$,'42501',null,'worker hash must match reserved server hash');
select throws_ok($$select public.complete_client_document_scan(current_setting('test.document_id')::uuid,repeat('a',64),'clean','test-scanner')$$,'55000',null,'worker cannot register absent blob as stored');
reset role;
insert into storage.objects(bucket_id,name) select 'client-intake-documents',object_path from private.client_document_versions;
set local role service_role;
select is((select receipt->>'scanStatus' from public.complete_client_document_scan(current_setting('test.document_id')::uuid,repeat('a',64),'clean','test-scanner')),'clean','server registers verified stored clean blob');
select lives_ok($$select public.complete_client_document_scan(current_setting('test.document_id')::uuid,repeat('a',64),'clean','test-scanner')$$,'identical scan registration is idempotent');
select throws_ok($$select public.complete_client_document_scan(current_setting('test.document_id')::uuid,repeat('a',64),'infected','test-scanner')$$,'23505',null,'terminal scan evidence cannot be rewritten');
reset role;
select set_config('request.jwt.claims',current_setting('test.document_original_jwt'),true);
set local role authenticated;
select is(pg_temp.doc_read()->'rows'->0->>'status','needs_review','clean upload still needs human review');
select is(pg_temp.doc_review()->>'reviewVersion','1','authorized human review writes version');
select is(pg_temp.doc_review()->>'replayed','true','review retry does not duplicate');
select is(pg_temp.doc_read()->'rows'->0->>'status','reviewed','review state reads back from database');
select is((select payload->>'expiresSeconds' from public.prepare_client_document_download('c2300000-0000-4000-8000-000000000001','c2400000-0000-4000-8000-000000000001','c2600000-0000-4000-8000-000000000001',current_setting('test.document_id')::uuid)),'60','download authorization is short lived');
select lives_ok($$select pg_temp.doc_review(jsonb_build_object('category','medication_history','expectedDocumentVersion',0,'decision','not_applicable','reason','經核對本案無歷史給藥文件','idempotency_key',gen_random_uuid()))$$,'not applicable is explicit and reasoned, not missing');
select is(pg_temp.doc_read()->'rows'->4->>'status','not_applicable','not applicable persists separately from missing');
select throws_ok($$select pg_temp.doc_reserve(jsonb_build_object('expectedDocumentVersion',1,'idempotency_key',gen_random_uuid()))$$,'23505',null,'same clean hash warns instead of duplicate file');
reset role;
select throws_ok($$update private.client_document_versions set sha256=repeat('b',64)$$,'55000',null,'attachment metadata immutable');
select throws_ok($$delete from private.client_document_scan_results$$,'55000',null,'scan evidence cannot be deleted');
select ok(exists(select 1 from public.audit_events where table_name='client_document_download'),'download authorization audited');
select ok(not exists(select 1 from public.audit_events where table_name like 'client_document%' and metadata::text like '%合成%'),'audit metadata contains no raw contact/file/review text');
set local role authenticated;
select is(pg_temp.doc_reserve()->'terminalReceipt'->>'scanStatus','clean','replayed reservation includes immutable terminal receipt without rescanning');
select throws_ok($$select pg_temp.doc_reserve(jsonb_build_object('category','health_exam','idempotency_key',gen_random_uuid(),'documentDate','2026-09-10','validUntil','2026-09-01'))$$,'22023',null,'document validity dates cannot be reversed');
select throws_ok($$select pg_temp.doc_reserve(jsonb_build_object('category','health_exam','idempotency_key',gen_random_uuid(),'periodFrom','2026-09-01'))$$,'22023',null,'medication history interval must have both boundaries');
select is(pg_temp.doc_reserve(jsonb_build_object('category','health_exam','idempotency_key',gen_random_uuid(),'documentLabel','合成體檢報告','provider','合成院所','documentDate','2026-09-01','validUntil','2027-09-01'))->>'version','1','provider and date metadata reserve alongside bytes');
select is((select h->>'provider' from jsonb_array_elements(pg_temp.doc_read()->'history')h where h->>'category'='health_exam'),'合成院所','history reads back exact provider metadata');
select is(jsonb_array_length(pg_temp.doc_read()->'history'),2,'new category retains prior attachment history');
reset role;
select set_config('test.document_health_id',(select id::text from private.client_document_versions where category='health_exam'),true);
insert into storage.objects(bucket_id,name) select 'client-intake-documents',object_path from private.client_document_versions where category='health_exam';
select set_config('request.jwt.claims','{"role":"service_role"}',true);
set local role service_role;
select receipt from public.complete_client_document_scan(current_setting('test.document_health_id')::uuid,repeat('a',64),'infected','test-scanner');
reset role;
select set_config('request.jwt.claims',current_setting('test.document_original_jwt'),true);
set local role authenticated;
select throws_ok($$select public.prepare_client_document_download('c2300000-0000-4000-8000-000000000001','c2400000-0000-4000-8000-000000000001','c2600000-0000-4000-8000-000000000001',current_setting('test.document_health_id')::uuid)$$,'42501',null,'infected stored attachment never gets download authorization');
reset role;
delete from public.role_permissions where role_id=(select id from public.roles where is_system and role_key='branch_supervisor') and permission_id=(select id from public.permissions where permission_key='clients.demographics.read');
set local role authenticated;
select is(pg_temp.doc_read()->'rows'->0->>'status','restricted','identity documents require demographics even when clients.manage remains');
select is((select count(*)::integer from jsonb_array_elements(pg_temp.doc_read()->'history')h where h->>'category' like 'identity_%'),0,'revoked demographics hides sensitive identity history');
select throws_ok($$select public.prepare_client_document_download('c2300000-0000-4000-8000-000000000001','c2400000-0000-4000-8000-000000000001','c2600000-0000-4000-8000-000000000001',current_setting('test.document_id')::uuid)$$,'42501',null,'revoked demographics blocks identity download');
select throws_ok($$select pg_temp.doc_reserve()$$,'42501',null,'revoked demographics blocks identity reservation replay');
select throws_ok($$select pg_temp.doc_review()$$,'42501',null,'revoked demographics blocks identity review replay');
reset role;
delete from public.membership_roles where membership_id='c2500000-0000-4000-8000-000000000001';
insert into public.membership_roles(membership_id,role_id) values('c2500000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000008');
insert into public.client_assignments(organization_id,branch_id,client_id,assignee_user_id,assignment_kind,starts_at) values('c2300000-0000-4000-8000-000000000001','c2400000-0000-4000-8000-000000000001','c2600000-0000-4000-8000-000000000001','c2100000-0000-4000-8000-000000000001','transport',now()-interval '1 year');
set local role authenticated;
select is((select count(*)::integer from jsonb_array_elements(pg_temp.doc_read()->'rows')r where r->>'status'='restricted'),6,'assigned driver sees no sensitive document categories');
select throws_ok($$select public.prepare_client_document_download('c2300000-0000-4000-8000-000000000001','c2400000-0000-4000-8000-000000000001','c2600000-0000-4000-8000-000000000001',current_setting('test.document_id')::uuid)$$,'42501',null,'driver cannot get identity download');
reset role;
select * from finish();
rollback;
